#!/usr/bin/env python3
"""bsf_bsr_dispatch.py IN OUT: IN = the splice generated by cpuid_dispatch.py (the whole replacement of two_byte_opcode_execute, so the splices compose); OUT = the same function with in addition the splice that makes two_byte_opcode_execute dispatch 0F BC (no mandatory prefix) to x86_bsf and 0F BD (no mandatory prefix) to x86_bsr.  TRANSCRIPTION of the dispatch of ACL2 master
3ccb342c88bd3b815856f4bbc336382287934405 inst-listing.lisp:10314-10317 (`(INST "BSF" (OP :OP #xFBC :PFX :NO-PREFIX) ... '(X86-BSF) '((:UD (UD-LOCK-USED))))`) and :10322-10325 (BSR, 0F BD, X86-BSR, same UD rule).
The pinned translation has, in two_byte_opcode_execute, no arm for 188 (its last lines are the `Translation error: two-byte opcode 188 not translated` arm of the fall-through list) and, for 189, the arm
`mandatory_prefix == 0x00 -> x86_model_error("Opcode Unimplemented in x86isa!")` (the 0xf3 arm, LZCNT, stays).  The script replaces exactly these two texts, each of which must occur exactly once in two_byte_opcode_execute."""
import sys

OLD188 = '          188 => throw(Emsg("Translation error: two-byte opcode 188 not translated")),\n'
NEW188 = """          188 => {
              if mandatory_prefix == 0x00 then {
                  if 0xf0 == prefixes[lck] then {
                      x86_fault("(:UD)")
                  };
                  x86_bsf(proc_mode, start_rip, temp_rip, prefixes, rex_byte, opcode, modr_m, sib)
              } else if mandatory_prefix == 0xf3 then {
                  x86_model_error("Opcode Unimplemented in x86isa!")
              } else {
                  x86_fault("(X86-ILLEGAL-INSTRUCTION \\"#UD Encountered!\\" START-RIP TEMP-RIP X86)")
              }
          },
"""
OLD189 = """          189 => {
              if mandatory_prefix == 0x00 then {
                  if 0xf0 == prefixes[lck] then {
                      x86_fault("(:UD)")
                  };
                  x86_model_error("Opcode Unimplemented in x86isa!")
"""
NEW189 = OLD189.replace('x86_model_error("Opcode Unimplemented in x86isa!")\n', 'x86_bsr(proc_mode, start_rip, temp_rip, prefixes, rex_byte, opcode, modr_m, sib)\n')
src = open(sys.argv[1]).read()
a = src.index('val two_byte_opcode_execute :')
b = src.index('\n}\n', src.index('function two_byte_opcode_execute (')) + 3
fn = src[a:b]
assert fn.count(OLD189) == 1, 'arm 189 of two_byte_opcode_execute not found exactly once'
assert NEW189 != OLD189
fn = fn.replace(OLD189, NEW189)
if fn.count(OLD188) == 1:
    fn = fn.replace(OLD188, '')                                   # the fall-through `not translated` arm: the real arm goes before arm 189
    assert fn.count(OLD189.replace('x86_model_error("Opcode Unimplemented in x86isa!")\n', 'x86_bsr(proc_mode, start_rip, temp_rip, prefixes, rex_byte, opcode, modr_m, sib)\n')) == 1
    fn = fn.replace('          189 => {', NEW188 + '          189 => {', 1)
else:
    raise SystemExit('the 188 fall-through arm was not found exactly once')
open(sys.argv[2], 'w').write("// GENERATED by bsf_bsr_dispatch.py from the model's two_byte_opcodes_dispatch.sail: arms 188 (0F BC) and 189 (0F BD) dispatch to x86_bsf / x86_bsr (ACL2 master inst-listing.lisp:10314-10325)\n" +
                             fn)
